(1957, 2, 1778767712, 'theme_academi', 'logo', '/Desain tanpa judul (15).png', '/logo.png'),
(1958, 2, 1778767713, 'theme_academi', 'favicon', '/Desain tanpa judul (15).png', ''),
(1959, 2, 1778767713, 'theme_academi', 'slide1image', '/Desain tanpa judul (16).png', '/slide1image.jpg'),
(1960, 2, 1778767713, 'theme_academi', 'slide1caption', 'Belajar makin asik, masa depan makin menarik!', 'Bootstrap Based Slider - 01'),
(1961, 2, 1778767713, 'theme_academi', 'slide1desc', 'Selamat Datang di AKSI Moodle LMS: Jembatan Menuju Keahlian Profesional!\r\n\r\nAKSI (Aktif, Kolaboratif, Solutif, dan Inovatif) hadir sebagai platform pembelajaran digital yang dirancang khusus untuk mendukung kebutuhan literasi teknis dan pengembangan keterampilan siswa SMK. Kami percaya bahwa pendidikan kejuruan bukan sekadar tentang teori, melainkan tentang pergerakan nyata menuju dunia industri.', 'Neque porro quisquam est qui dolorem ipsum quia dolor sit amet, consectetur, adipisci velit.'),
(1962, 2, 1778770099, 'theme_academi', 'primarycolor', '#0364B4', ''),
